    38→function downloadCSV(filename: string, headers: string[], rows: string[][]) {
    39→  const csv = [
    40→    headers.join(","),
    41→    ...rows.map(r => r.map(v => `"${String(v ?? "").replace(/"/g, '""')}"`).join(",")),
    42→  ].join("\n");
    43→  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    44→  const url = URL.createObjectURL(blob);
    45→  const a = document.createElement("a");
    46→  a.href = url; a.download = filename; a.click();
    47→  URL.revokeObjectURL(url);
    48→}
