   246→function WeekView({ currentDate, events, onEventClick }: {
   247→  currentDate: Date; events: CalendarEvent[]; onEventClick: (e: CalendarEvent) => void;
   248→}) {
   249→  const startOfWeek = new Date(currentDate);
   250→  startOfWeek.setDate(currentDate.getDate() - currentDate.getDay());
   251→  const days = Array.from({ length: 7 }, (_, i) => { const d = new Date(startOfWeek); d.setDate(d.getDate() + i); return d; });
   252→  const hours = Array.from({ length: 24 }, (_, i) => i);
   253→  const today = new Date().toDateString();
   254→
   255→  const eventsForDay = (date: Date) => {
   256→    const dateStr = `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;
   257→    return events.filter(e => e.date === dateStr);
