   267→            <p className="text-xs text-muted-foreground">{DAY_NAMES[d.getDay()]}</p>
   268→            <p className={cn("text-sm font-bold w-7 h-7 rounded-full flex items-center justify-center mx-auto", d.toDateString() === today ? "bg-primary text-primary-foreground" : "text-foreground")}>{d.getDate()}</p>
