    94→  const unreadCount = notifs.filter(n => !n.read).length;
    95→
    96→  const filtered = notifs.filter(n => {
    97→    const matchesSearch = search === "" || 
    98→      n.title.toLowerCase().includes(search.toLowerCase()) ||
    99→      n.message.toLowerCase().includes(search.toLowerCase());
   100→    if (!matchesSearch) return false;
   101→    if (activeFilter === "All") return true;
   102→    if (activeFilter === "Unread") return !n.read;
   103→    return getNotifStatus(n) === activeFilter;
   104→  });
   105→
   106→  const getTabCount = (tab: FilterTab): number => {
   107→    if (tab === "All") return notifs.filter(n => !n.read).length;
   108→    if (tab === "Unread") return notifs.filter(n => !n.read).length;
   109→    return notifs.filter(n => getNotifStatus(n) === tab && !n.read).length;
   110→  };
   111→
   112→  return (
   113→    <div className="max-w-4xl mx-auto space-y-5">
   114→      {/* Header */}
   115→      <div className="flex items-center justify-between">
   116→        <div className="flex items-center gap-3">
   117→          <h1 className="text-3xl font-bold tracking-tight">Notifications</h1>
   118→          {unreadCount > 0 && (
   119→            <Badge className="bg-primary text-primary-foreground rounded-full px-2.5 py-0.5 text-xs font-bold">
   120→              {unreadCount}
   121→            </Badge>
   122→          )}
   123→        </div>
   124→        <Button
   125→          variant="outline"
   126→          size="sm"
   127→          className="gap-2"
   128→          onClick={markAllRead}
   129→          disabled={unreadCount === 0}
   130→        >
   131→          <CheckCheck size={15} /> Mark all read
   132→        </Button>
   133→      </div>
   134→
   135→      <div className="bg-card border rounded-2xl shadow-sm overflow-hidden">
   136→        {/* Search + Filters */}
   137→        <div className="border-b px-5 pt-4 pb-0 space-y-3">
   138→          <div className="relative">
   139→            <Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" />
   140→            <Input
   141→              placeholder="Search notifications…"
   142→              className="pl-9 h-9 text-sm bg-muted/30 border-0 focus-visible:ring-1"
   143→              value={search}
   144→              onChange={e => setSearch(e.target.value)}
   145→            />
   146→          </div>
   147→
   148→          {/* Status filter tabs */}
   149→          <div className="flex gap-0 overflow-x-auto">
   150→            {FILTER_TABS.map(tab => {
   151→              const count = getTabCount(tab);
   152→              const isActive = activeFilter === tab;
   153→              return (
   154→                <button
   155→                  key={tab}
   156→                  onClick={() => setActiveFilter(tab)}
   157→                  className={`flex items-center gap-1.5 px-4 py-2.5 text-sm font-medium border-b-2 whitespace-nowrap transition-colors ${
   158→                    isActive
   159→                      ? "border-primary text-primary"
   160→                      : "border-transparent text-muted-foreground hover:text-foreground"
   161→                  }`}
   162→                >
   163→                  {tab}
   164→                  {count > 0 && (
   165→                    <span className={`text-[10px] font-bold rounded-full px-1.5 py-0.5 leading-none min-w-[18px] text-center ${
   166→                      isActive ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"
   167→                    }`}>
   168→                      {count}
   169→                    </span>
   170→                  )}
   171→                </button>
   172→              );
   173→            })}
   174→          </div>
   175→        </div>
   176→
   177→        {/* Notification list */}
   178→        <div className="divide-y">
   179→          {filtered.length > 0 ? (
   180→            filtered.map(notif => (
   181→              <NotificationItem
   182→                key={notif.id}
   183→                notif={notif}
   184→                onRead={markRead}
   185→                onDelete={deleteNotif}
   186→              />
   187→            ))
   188→          ) : (
   189→            <div className="text-center py-20 text-muted-foreground">
   190→              <Bell className="mx-auto h-10 w-10 opacity-20 mb-4" />
   191→              <p className="font-medium">No notifications here.</p>
   192→              <p className="text-sm mt-1">
   193→                {search ? "Try a different search term." : `You have no ${activeFilter.toLowerCase()} notifications.`}
   194→              </p>
   195→            </div>
   196→          )}
   197→        </div>
   198→
   199→        {filtered.length > 0 && (
   200→          <div className="px-5 py-3 border-t bg-muted/20 text-xs text-muted-foreground flex justify-between">
   201→            <span>Showing {filtered.length} of {notifs.length} notifications</span>
   202→            <span>{unreadCount} unread</span>
   203→          </div>
   204→        )}
   205→      </div>
   206→    </div>
   207→  );
   208→}
